makeMinigun:
function makeMinigun() {
  const gun = new THREE.Group();
  const K = gunKit(gun);
  // Housing: one moulded body with a round back end, bolted side plates, cooling slots, the hub showing.
  K.slab([[0.225, -0.13], [0.225, 0.13], ...gunArc(-0.32, 0, 0.13, Math.PI / 2, Math.PI * 1.5, 10)], 0.28, gunBody, { bevel: 0.035, segs: 3 });
  for (const sx of [-1, 1]) {
    K.box(0.02, 0.2, 0.42, gunMid, sx * 0.145, 0.0, -0.05);
    for (let i = 0; i < 5; i++) K.box(0.024, 0.012, 0.28, gunDark, sx * 0.146, 0.07 - i * 0.035, -0.06);
    for (const [by, bz] of [[0.085, 0.13], [0.085, -0.24], [-0.085, 0.13], [-0.085, -0.24]]) K.cyl(0.011, 0.011, 0.012, gunAccent, sx * 0.157, by, bz, null, 6, 'x');
  }
  K.cyl(0.07, 0.07, 0.3, gunDark, 0, -0.02, -0.32, null, 12, 'x');
  // Drive motor under the housing, finned, with its power lead.
  const fins = [[0, -0.18], [0.072, -0.18]];
  for (let i = 0; i < 6; i++) { const z = -0.15 + i * 0.04; fins.push([0.072, z - 0.006], [0.084, z - 0.006], [0.084, z + 0.006], [0.072, z + 0.006]); }
  fins.push([0.072, 0.08], [0, 0.08]);
  K.lathe(fins, gunDark, { y: -0.18, seg: 14 });
  K.cyl(0.012, 0.012, 0.3, gunRubber, -0.08, -0.2, -0.2, null, 6).rotation.set(Math.PI / 2, 0, 0.3);
  // Top grip with finger grooves, and a carry handle arching over the housing.
  K.slab([[-0.262, 0.09], [-0.25, 0.14], [-0.256, 0.165], [-0.24, 0.19], [-0.244, 0.215], [-0.228, 0.24], [-0.21, 0.29], [-0.212, 0.302],
          [-0.3, 0.32], [-0.306, 0.31], [-0.35, 0.105], [-0.35, 0.09]], 0.068, gunPoly, { bevel: 0.016, segs: 3 });
  for (const z of [-0.12, 0.12]) K.box(0.03, 0.12, 0.03, gunDark, 0, 0.18, z);
  K.box(0.03, 0.03, 0.27, gunDark, 0, 0.24, 0);
  K.box(0.05, 0.035, 0.18, gunRubber, 0, 0.26, 0);
  // Face plate and a spindle hub for the barrel cluster.
  K.lathe([[0, 0.21], [0.126, 0.21], [0.132, 0.216], [0.132, 0.264], [0.126, 0.27], [0, 0.27]], gunMid, { seg: 20 });
  for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; K.cyl(0.01, 0.01, 0.07, gunAccent, Math.cos(a) * 0.11, Math.sin(a) * 0.11, 0.24, null, 6); }
  const barrelAssembly = new THREE.Group();
  barrelAssembly.position.set(0, 0, 0.27);
  const barrelLen = 0.72, barrelR = 0.028, clusterR = 0.075;
  K.cyl(0.03, 0.03, barrelLen, gunDark, 0, 0, barrelLen / 2, barrelAssembly, 10);
  for (let i = 0; i < 6; i++) {
    const ang = (i / 6) * Math.PI * 2, bx = Math.cos(ang) * clusterR, by = Math.sin(ang) * clusterR;
    K.cyl(barrelR * 0.85, barrelR, barrelLen, gunAccent, bx, by, barrelLen / 2, barrelAssembly, 10);
    K.lathe([[0, barrelLen - 0.04], [barrelR * 1.08, barrelLen - 0.04], [barrelR * 1.08, barrelLen + 0.008], [barrelR * 0.5, barrelLen + 0.01], [barrelR * 0.5, barrelLen + 0.004], [0, barrelLen + 0.004]], gunDark, { x: bx, y: by, parent: barrelAssembly, seg: 10 });
  }
  [0.04, 0.28, 0.36, 0.68].forEach((rz, i) => K.tor([0.12, 0.115, 0.115, 0.11][i], 0.018, gunMid, 0, 0, rz, 0, 0, 0, barrelAssembly));
  K.lathe([[0, 0.345], [0.108, 0.345], [0.112, 0.35], [0.112, 0.37], [0.108, 0.375], [0, 0.375]], gunBody, { parent: barrelAssembly, seg: 18 });
  gun.add(barrelAssembly);
  // Ammo box on the right, a feed chute of links running up into the housing, the belt of brass at its mouth.
  const ammoBox = new THREE.Group();
  ammoBox.position.set(0.2, -0.08, -0.02);
  ammoBox.rotation.z = 0.12;
  K.box(0.16, 0.14, 0.22, gunOlive, 0, 0, 0, 0, 0, 0, ammoBox, 0.015);
  K.box(0.17, 0.02, 0.23, gunDark, 0, 0.075, 0, 0, 0, 0, ammoBox, 0.006);
  K.box(0.06, 0.012, 0.02, gunDark, 0, 0.09, 0, 0, 0, 0, ammoBox, 0.004);
  K.box(0.002, 0.05, 0.1, hazardYellow, 0.081, 0.0, 0.0, 0, 0, 0, ammoBox, 0.001);
  for (let i = 0; i < 4; i++) K.cyl(0.011, 0.011, 0.07, brassMat, -0.04 + i * 0.026, 0.09, 0.05, ammoBox, 6, 'x');
  gun.add(ammoBox);
  for (let i = 0; i < 5; i++) {
    const u = i / 4;
    K.box(0.06, 0.03, 0.06, gunDark, 0.19 - u * 0.05, -0.0 + u * 0.1, 0.05 - u * 0.05, 0, 0, -0.5 - u * 0.5, null, 0.01);
  }
  gunEffects(gun, new THREE.Vector3(0, 0, 0.27 + barrelLen + 0.02), 0.08, 4, 8, 0.008);
  gun.userData.laser.position.set(0, 0, 0.27 + barrelLen + 4);
  gun.userData.laserBaseZ = 0.27 + barrelLen;
  gun.userData.barrelAssembly = barrelAssembly;
  gun.userData.ammoBox = ammoBox;
  gun.userData.mag = ammoBox;
  gun.userData.baseBarrelRotX = 0;
  gun.userData.baseAmmoPos = ammoBox.position.clone();
  gun.userData.baseAmmoRot = ammoBox.rotation.clone();
  return finishGun(gun);
}

makePistol:
function makePistol() {
  const gun = new THREE.Group();
  const K = gunKit(gun);
  // Slide (moves): chamfered top, rear and front serrations, sights, the ejection port and extractor.
  const slide = K.group(0, 0.05, 0.05);
  K.slab([[-0.14, -0.042], [0.14, -0.042], [0.14, 0.03], [0.133, 0.047], [0.12, 0.055], [-0.13, 0.055], [-0.14, 0.046]], 0.072, gunBody, { bevel: 0.007, segs: 1, parent: slide });
  for (let i = 0; i < 7; i++) for (const sx of [-1, 1]) K.box(0.003, 0.058, 0.005, gunDark, sx * 0.0355, 0.004, -0.128 + i * 0.01, 0, 0, 0, slide);
  for (let i = 0; i < 4; i++) for (const sx of [-1, 1]) K.box(0.003, 0.048, 0.005, gunDark, sx * 0.0355, 0.006, 0.088 + i * 0.01, 0, 0, 0, slide);
  K.slab([[-0.128, 0.052], [-0.098, 0.052], [-0.102, 0.072], [-0.124, 0.072]], 0.032, gunDark, { bevel: 0.003, parent: slide });
  for (const sx of [-1, 1]) K.box(0.005, 0.006, 0.002, gaugeFace, sx * 0.008, 0.066, -0.1285, 0, 0, 0, slide);
  K.slab([[0.1, 0.052], [0.122, 0.052], [0.118, 0.068], [0.106, 0.068]], 0.01, gunDark, { bevel: 0.002, parent: slide });
  K.box(0.005, 0.005, 0.002, sightDotMat, 0, 0.064, 0.0995, 0, 0, 0, slide);
  K.box(0.004, 0.028, 0.062, gunRubber, 0.036, 0.022, 0.02, 0, 0, 0, slide);
  K.box(0.004, 0.008, 0.04, gunDark, 0.0365, 0.008, -0.03, 0, 0, 0, slide);
  // Barrel hood lives on the frame (below), not the slide — otherwise reload rack
  // peels a gunAccent chunk off the muzzle and reads as the barrel detaching.
  // Frame: the dust cover with an accessory rail, the trigger guard, trigger, controls.
  K.slab([[-0.1, 0.013], [0.17, 0.013], [0.172, -0.028], [0.162, -0.034], [0.13, -0.034], [0.124, -0.028], [0.02, -0.03], [-0.02, -0.028], [-0.1, -0.018]], 0.066, gunPoly, { bevel: 0.008 });
  K.rail(0.07, 0, -0.04, 0.15, null, 0.04);
  K.slab(gunBand([[0.128, -0.028], [0.128, -0.07], [0.116, -0.082], [0.04, -0.082], [0.022, -0.07], [0.014, -0.05]], 0.0055), 0.016, gunPoly, { bevel: 0.004 });
  K.slab(gunBand([[0.075, -0.028], [0.073, -0.05], [0.066, -0.068]], 0.004), 0.012, gunDark, { bevel: 0.002 });
  K.box(0.006, 0.014, 0.04, gunDark, -0.034, 0.008, 0.06);                               // slide stop
  K.box(0.006, 0.02, 0.02, gunDark, -0.034, -0.02, 0.03);                                // mag release
  // Grip: a beavertail, texture panels, the magazine's base below.
  K.slab(gripOutline(-0.02, -0.08, 0.18, 0.1, 0.25, 1.6), 0.066, gunPoly, { bevel: 0.014, segs: 3 });
  for (const sx of [-1, 1]) K.slab([[0.02, -0.07], [0.008, -0.145], [-0.058, -0.128], [-0.048, -0.06]], 0.004, gunRubber, { x: sx * 0.032, bevel: 0.001 });
  const mag = K.group(0, -0.14, -0.01);
  K.slab([[-0.04, 0.06], [0.04, 0.06], [0.04, -0.06], [-0.04, -0.06]], 0.054, magPoly, { bevel: 0.005, rx: 0.25, parent: mag });
  K.slab([[-0.054, -0.058], [0.046, -0.058], [0.048, -0.074], [-0.056, -0.078]], 0.064, magPoly, { bevel: 0.006, rx: 0.25, parent: mag });
  gun.userData.slide = slide;
  gun.userData.mag = mag;
  gun.userData.baseSlidePos = slide.position.clone();
  gun.userData.baseMagPos = mag.position.clone();
  gun.userData.baseMagRot = mag.rotation.clone();
  // Barrel + compensator locked to the frame group (receiver). Slide is a sibling
  // that racks over them on reload. Barrel is lengthened rearward into the dust
  // cover so a racked slide never leaves the muzzle floating off the gun body
  // (see kickPistolRecoil / slideKick). Reload slide travel is 0.13 — barrel must
  // stay continuous through that full rack (no floating stub in the ejection window).
  const frame = K.group(0, 0, 0);
  // Dust-cover shelf under the barrel — bridges polymer receiver to muzzle so the
  // barrel stays visually locked when the slide racks back on reload.
  K.box(0.062, 0.028, 0.26, gunPoly, 0, 0.018, 0.12, 0, 0, 0, frame, 0.01);
  K.box(0.055, 0.02, 0.20, gunDark, 0, 0.036, 0.09, 0, 0, 0, frame, 0.006);          // chamber block
  K.box(0.03, 0.022, 0.07, gunAccent, 0.0, 0.055, 0.09, 0, 0, 0, frame, 0.006);      // barrel hood (frame-locked)
  K.lathe([[0, -0.02], [0.0145, -0.02], [0.0145, 0.262], [0, 0.262]], gunAccent, { y: 0.05, seg: 12, parent: frame });
  K.slab([[0.232, 0.024], [0.306, 0.024], [0.31, 0.068], [0.3, 0.075], [0.24, 0.075], [0.232, 0.068]], 0.05, gunDark, { bevel: 0.008, parent: frame });
  for (let i = 0; i < 3; i++) K.box(0.03, 0.006, 0.01, gunRubber, 0, 0.076, 0.25 + i * 0.018, 0, 0, 0, frame);
  K.disc(0.012, gunRubber, 0, 0.05, 0.3105, 0, frame, 10);
  gun.userData.frame = frame;
  gunEffects(gun, new THREE.Vector3(0, 0.05, 0.32), 0.045, 2.5, 6, 0.005);
  gun.userData.laser.position.set(0, 0.05, 3.3);
  gun.userData.laserBaseZ = 0.3;
  gun.userData.barrelAssembly = null;
  gunSuppressor(gun, K, 'pistol');   // CL-95
  return finishGun(gun);
}

makeUzi:
function makeUzi() {
  const gun = new THREE.Group();
  const K = gunKit(gun);
  // Stamped receiver with pressed ribs; the top cover and its cocking knob.
  K.slab([[-0.14, -0.04], [0.22, -0.04], [0.22, 0.078], [-0.122, 0.078], [-0.14, 0.06]], 0.098, gunBody, { bevel: 0.01 });
  for (const sx of [-1, 1]) for (let i = 0; i < 3; i++) K.box(0.006, 0.012, 0.3, gunMid, sx * 0.0495, 0.05 - i * 0.035, 0.04);
  K.slab([[-0.13, 0.074], [0.2, 0.074], [0.2, 0.098], [-0.11, 0.104], [-0.13, 0.094]], 0.09, gunMid, { bevel: 0.012 });
  K.cyl(0.014, 0.014, 0.03, gunDark, 0, 0.114, 0.11, null, 8, 'y');
  K.sph(0.016, gunDark, 0, 0.13, 0.11);
  // Sights with their protective ears.
  for (const sx of [-1, 1]) { K.box(0.008, 0.045, 0.03, gunAccent, sx * 0.022, 0.124, -0.08); K.box(0.008, 0.04, 0.02, gunAccent, sx * 0.018, 0.114, 0.2); }
  K.box(0.022, 0.03, 0.02, gunAccent, 0, 0.12, -0.08);
  K.box(0.005, 0.03, 0.006, gunAccent, 0, 0.115, 0.2);
  // Folding stock: struts along the sides and the butt plate.
  K.box(0.05, 0.06, 0.1, gunDark, 0, 0.04, -0.18, -0.15, 0, 0, null, 0.012);
  for (const sx of [-1, 1]) K.box(0.01, 0.012, 0.22, gunMid, sx * 0.04, 0.02, -0.12, 0.05);
  K.box(0.09, 0.06, 0.015, gunDark, 0, 0.0, -0.24, 0, 0, 0, null, 0.005);
  K.box(0.03, 0.03, 0.12, gunMid, 0.04, 0.05, -0.16, 0, 0.45, 0);
  // Grip with the grip safety at the back, the big trigger guard, trigger, selector.
  K.slab(gripOutline(-0.02, -0.1, 0.16, 0.08, 0.22, 0.2), 0.064, gunPoly, { bevel: 0.014, segs: 3 });
  K.box(0.03, 0.07, 0.02, gunDark, 0, -0.08, -0.07, 0.22);
  K.slab(gunBand([[0.088, -0.04], [0.09, -0.068], [0.078, -0.079], [0.03, -0.079], [0.018, -0.07]], 0.005), 0.014, gunDark, { bevel: 0.003 });
  K.slab(gunBand([[0.052, -0.04], [0.05, -0.056], [0.044, -0.066]], 0.0035), 0.01, gunAccent, { bevel: 0.002 });
  K.box(0.006, 0.02, 0.02, gunDark, -0.052, -0.02, 0.0);
  // The narrow magazine passes through the grip. Bake its rake into the inner
  // assembly: reload animates the outer group back to zero at insertion.
  const mag = K.group(0, -0.205, -0.0435);
  const stick = new THREE.Group(); stick.rotation.x = 0.22; mag.add(stick);
  K.slab([[-0.022, 0.115], [0.022, 0.115], [0.022, -0.109], [-0.022, -0.109]], 0.036, gunAccent, { bevel: 0.003, parent: stick });
  for (const sx of [-1, 1]) K.box(0.003, 0.18, 0.006, gunDark, sx * 0.0185, 0, 0, 0, 0, 0, stick);
  K.slab([[-0.026, -0.106], [0.026, -0.106], [0.026, -0.119], [-0.026, -0.119]], 0.042, gunDark, { bevel: 0.003, parent: stick });
  gun.userData.mag = mag;
  gun.userData.baseMagPos = mag.position.clone();
  gun.userData.baseMagRot = mag.rotation.clone();
  // Front of the receiver, the knurled barrel nut, the threaded barrel.
  K.slab([[0.18, -0.01], [0.34, -0.01], [0.34, 0.07], [0.18, 0.07]], 0.08, gunMid, { bevel: 0.016, segs: 3 });
  K.lathe([[0, 0.325], [0.035, 0.325], [0.035, 0.355], [0, 0.355]], gunDark, { y: 0.03, seg: 16 });
  for (let i = 0; i < 12; i++) { const a = i / 12 * Math.PI * 2; K.box(0.006, 0.006, 0.03, gunAccent, Math.cos(a) * 0.036, 0.03 + Math.sin(a) * 0.036, 0.34); }
  K.lathe([[0, 0.34], [0.017, 0.34], [0.017, 0.455], [0.02, 0.458], [0.02, 0.475], [0.012, 0.478], [0, 0.478]], gunAccent, { y: 0.03, seg: 12 });
  gunEffects(gun, new THREE.Vector3(0, 0.03, 0.48), 0.05, 2.8, 7, 0.005);
  gun.userData.laser.position.set(0, 0.03, 4.0);
  gun.userData.laserBaseZ = 0.45;
  gun.userData.barrelAssembly = null;
  gun.userData.slide = null;
  gunSuppressor(gun, K, 'uzi');   // CL-95
  return finishGun(gun);
}

makeShotgun:
function makeShotgun() {
  const gun = new THREE.Group();
  const K = gunKit(gun);
  // Receiver: the high back sloping to the stock, the ejection and loading ports, a sidesaddle of shells, the tang safety.
  K.slab([[-0.19, 0.06], [-0.19, -0.036], [-0.172, -0.046], [0.23, -0.046], [0.23, 0.07], [0.216, 0.084], [-0.15, 0.084]], 0.108, gunBody, { bevel: 0.012 });
  K.box(0.004, 0.045, 0.12, gunRubber, 0.055, 0.035, 0.06);
  K.box(0.05, 0.004, 0.14, gunRubber, 0, -0.047, 0.08);
  K.slab([[-0.07, 0.058], [0.13, 0.058], [0.13, -0.018], [-0.07, -0.018]], 0.012, gunPoly, { x: -0.06, bevel: 0.004 });
  for (let i = 0; i < 5; i++) {
    K.cyl(0.015, 0.015, 0.065, shellRedMat, -0.078, 0.02, -0.04 + i * 0.035, null, 8, 'y');
    K.cyl(0.016, 0.016, 0.014, brassMat, -0.078, -0.018, -0.04 + i * 0.035, null, 8, 'y');
  }
  K.box(0.018, 0.008, 0.022, gunDark, 0, 0.087, -0.13, 0, 0, 0, null, 0.003);
  // Stock with a recoil pad; the pistol grip, trigger guard and trigger; a sling loop.
  K.slab([[-0.186, 0.066], [-0.45, 0.05], [-0.462, 0.052], [-0.468, -0.088], [-0.46, -0.092], [-0.36, -0.07], [-0.25, -0.05], [-0.186, -0.038]], 0.084, gunPoly, { bevel: 0.018, segs: 3 });
  K.slab([[-0.494, 0.055], [-0.464, 0.054], [-0.47, -0.092], [-0.496, -0.095]], 0.088, gunRubber, { bevel: 0.008 });
  K.slab(gripOutline(-0.06, -0.1, 0.16, 0.08, 0.28), 0.066, gunPoly, { bevel: 0.014, segs: 3 });
  K.slab(gunBand([[0.05, -0.044], [0.05, -0.068], [0.04, -0.078], [0.006, -0.078], [-0.008, -0.068]], 0.004), 0.014, gunDark, { bevel: 0.002 });
  K.slab(gunBand([[0.024, -0.044], [0.023, -0.058], [0.016, -0.068]], 0.0032), 0.008, gunAccent, { bevel: 0.002 });
  K.tor(0.012, 0.004, gunDark, 0, -0.088, -0.4, 0, Math.PI / 2, 0);
  // Pump (moves): a rounded fore-end with grip rings.
  const pump = K.group(0, -0.02, 0.28);
  K.slab([[-0.11, 0.042], [0.11, 0.042], [0.11, -0.034], [0.098, -0.048], [-0.098, -0.048], [-0.11, -0.034]], 0.098, gunPoly, { bevel: 0.028, segs: 3, parent: pump });
  for (let i = 0; i < 6; i++) K.box(0.1, 0.092, 0.01, gunRubber, 0, -0.003, -0.08 + i * 0.032, 0, 0, 0, pump, 0.02);
  gun.userData.pump = pump;
  gun.userData.basePumpPos = pump.position.clone();
  // Barrel + mag tube locked to the receiver (sibling of pump). Pump racks along the
  // tube; these must NOT share the pump transform or they float away on fire/pump.
  // Lengthened + extended rearward so they always overlap the forend travel (0.24)
  // and the receiver — short tubes used to leave a visible gap when the pump racked.
  const receiver = K.group(0, 0, 0);
  K.lathe([[0, 0.16], [0.03, 0.16], [0.03, 0.935], [0, 0.935]], gunAccent, { y: 0.03, seg: 14, parent: receiver });
  K.box(0.016, 0.006, 0.72, gunDark, 0, 0.066, 0.56, 0, 0, 0, receiver);
  for (let i = 0; i < 14; i++) K.box(0.006, 0.008, 0.008, gunDark, 0, 0.06, 0.22 + i * 0.05, 0, 0, 0, receiver);
  K.sph(0.0075, brassMat, 0, 0.074, 0.915, receiver);
  K.lathe([[0, 0.11], [0.022, 0.11], [0.022, 0.8], [0, 0.8]], gunDark, { y: -0.04, seg: 12, parent: receiver });
  K.lathe([[0, 0.795], [0.026, 0.795], [0.026, 0.825], [0.02, 0.84], [0, 0.84]], gunBody, { y: -0.04, seg: 12, parent: receiver });
  K.box(0.04, 0.11, 0.025, gunDark, 0, -0.005, 0.76, 0, 0, 0, receiver, 0.008);
  K.tor(0.012, 0.004, gunDark, 0, -0.07, 0.76, 0, Math.PI / 2, 0, receiver);
  K.lathe([[0, 0.92], [0.035, 0.92], [0.035, 0.95], [0.031, 0.952], [0.022, 0.952], [0.022, 0.945], [0, 0.945]], gunDark, { y: 0.03, seg: 14, parent: receiver });
  gun.userData.receiver = receiver;
  gunEffects(gun, new THREE.Vector3(0, 0.03, 0.97), 0.07, 3.2, 7);
  gun.userData.laser.position.set(0, 0.03, 4.5);
  gun.userData.laserBaseZ = 0.99;
  gun.userData.barrelAssembly = null;
  // Tube-load shell flash (hidden until reload insert beats)
  const loadShell = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.015, 0.04, 8), shellRedMat);
  const loadRim = new THREE.Mesh(new THREE.CylinderGeometry(0.0155, 0.0155, 0.007, 8), brassMat);
  loadRim.position.y = -0.017;
  loadShell.add(loadRim);
  loadShell.rotation.x = Math.PI / 2;
  // Near magazine-tube loading port (under receiver / rear of tube)
  loadShell.position.set(0.02, -0.05, 0.22);
  loadShell.visible = false;
  gun.add(loadShell);
  gun.userData.reloadShell = loadShell;
  gun.userData.baseReloadShellPos = loadShell.position.clone();
  gunSuppressor(gun, K, 'shotgun');   // CL-95
  return finishGun(gun);
}

makeLauncher:
function makeLauncher() {
